export function metaSalesDailyStepsDueBy(ageInDays: number): MetaSalesStep[] {
  if (!Number.isFinite(ageInDays) || ageInDays < 1 || ageInDays > META_SALES_DAILY_WINDOW_DAYS) return [];
  return META_SALES_DAILY_STEPS.filter((step) => step.day <= ageInDays);
}

export const renderMetaSalesDailyStep = renderMetaSalesStep;
